// src/utils/order-amount/index.ts
function centsFromDecimal(value) {
  const match = /^(\d+)(?:\.(\d{1,2}))?$/.exec(value);
  if (!match)
    throw new Error("Invalid monetary amount");
  return BigInt(match[1]) * 100n + BigInt((match[2] ?? "").padEnd(2, "0"));
}
function decimalFromCents(cents) {
  return `${cents / 100n}.${(cents % 100n).toString().padStart(2, "0")}`;
}
function quantityToHundredths(quantity) {
  if (!Number.isFinite(quantity) || quantity < 0.01 || quantity > 99999999) {
    return null;
  }
  const match = /^(0|[1-9]\d*)(?:\.(\d{1,2}))?$/.exec(String(quantity));
  if (!match)
    return null;
  return BigInt(match[1]) * 100n + BigInt((match[2] ?? "").padEnd(2, "0"));
}
function priceToCents(price) {
  if (!Number.isFinite(price) || price < 1 || price > 99999999.99)
    return null;
  const match = /^(\d+)(?:\.(\d{1,2}))?$/.exec(String(price));
  if (!match)
    return null;
  return BigInt(match[1]) * 100n + BigInt((match[2] ?? "").padEnd(2, "0"));
}
function multiplyPrice(price, quantity) {
  const hundredths = quantityToHundredths(quantity);
  if (hundredths === null)
    throw new Error("Invalid quantity");
  return decimalFromCents((centsFromDecimal(price) * hundredths + 50n) / 100n);
}
function sumAmounts(amounts) {
  return decimalFromCents(amounts.reduce((total, amount) => total + centsFromDecimal(amount), 0n));
}

// src/utils/seller-profile-completion/index.ts
function isSellerProfileComplete(profile) {
  return !!profile?.isCurrent && !!profile.shopName.trim() && !!profile.detailAddress.trim() && (profile.phoneNumber?.trim().length ?? 0) >= 7 && profile.latitude !== null && Number.isFinite(profile.latitude) && profile.latitude >= -90 && profile.latitude <= 90 && profile.longitude !== null && Number.isFinite(profile.longitude) && profile.longitude >= -180 && profile.longitude <= 180;
}

// src/utils/seller-access/index.ts
async function requireVerifiedSeller(tx, sellerId, requireProfile = true) {
  const [account] = await tx.select({
    isActive: user.isActive,
    roles: user.role,
    emailVerified: user.emailVerified
  }).from(user).where(eq(user.id, sellerId)).limit(1);
  if (!account?.isActive)
    throw new OrderError(403, "Account is inactive");
  if (!account.emailVerified) {
    throw new OrderError(403, "Email OTP verification is required");
  }
  if (requireProfile) {
    if (!account.roles?.includes("seller"))
      throw new OrderError(403, "Seller role required");
    const [profile] = await tx.select().from(sellers_profile).where(and(eq(sellers_profile.userId, sellerId), eq(sellers_profile.isCurrent, true))).limit(1);
    if (!isSellerProfileComplete(profile))
      throw new OrderError(403, "Complete seller profile required");
  }
}
async function requireSellerScanAccess(tx, sellerId, orderId) {
  const [account] = await tx.select({ isActive: user.isActive, roles: user.role }).from(user).where(eq(user.id, sellerId)).limit(1);
  if (!account?.isActive || !account.roles?.includes("seller")) {
    throw new OrderError(403, "Seller account is inactive");
  }
  try {
    await requireVerifiedSeller(tx, sellerId);
    return;
  } catch (error) {
    if (!(error instanceof OrderError) || error.statusCode !== 403)
      throw error;
  }
  const [grace] = await tx.select({ graceUntil: seller_scan_grace.graceUntil }).from(seller_scan_grace).where(and(eq(seller_scan_grace.orderId, orderId), eq(seller_scan_grace.sellerId, sellerId))).limit(1);
  if (!grace || grace.graceUntil <= new Date) {
    throw new OrderError(403, "Email verification and a complete seller profile are required");
  }
}
async function sellerReadableOrderIds(tx, sellerId) {
  const [account] = await tx.select({ isActive: user.isActive, roles: user.role }).from(user).where(eq(user.id, sellerId)).limit(1);
  if (!account?.isActive || !account.roles?.includes("seller"))
    throw new OrderError(403, "Seller account is inactive");
  try {
    await requireVerifiedSeller(tx, sellerId);
    return null;
  } catch (error) {
    if (!(error instanceof OrderError) || error.statusCode !== 403)
      throw error;
  }
  const rows = await tx.select({ orderId: seller_scan_grace.orderId }).from(seller_scan_grace).where(and(eq(seller_scan_grace.sellerId, sellerId), gt(seller_scan_grace.graceUntil, new Date)));
  return rows.map((row) => row.orderId);
}

// src/utils/product-threshold/index.ts
function validateLowStockThreshold(value) {
  if (value == null)
    return;
  const scaled = value * 100;
  if (!Number.isFinite(value) || value < 0 || value > 99999999.99 || Math.abs(scaled - Math.round(scaled)) > 0.00001) {
    throw new OrderError(400, "Low-stock threshold must be nonnegative with at most two decimal places");
  }
}

