// src/modules/seller/services/seller.profile.avatar.ts
async function updateSellerAvatar(userId, file) {
  if (!file) {
    throw new OrderError(400, "No image file provided");
  }
  const arrayBuffer = await file.arrayBuffer();
  const buffer = Buffer.from(arrayBuffer);
  const ext = file.type === "image/png" ? "png" : file.type === "image/webp" ? "webp" : "jpg";
  const key = `avatars/${userId}/${Date.now()}.${ext}`;
  try {
    const imageUrl = await uploadToS3({
      buffer,
      key,
      contentType: file.type || "image/jpeg"
    });
    await db2.update(user).set({ image: imageUrl }).where(eq(user.id, userId));
    return { success: true, imageUrl };
  } catch (err) {
    console.error("[S3 Avatar Upload Error]:", err);
    throw new Error(err?.message || "Failed to upload profile picture to AWS S3");
  }
}

