// src/modules/seller/services/seller.product.update.ts
function updateSellerProduct(sellerId, productId, body) {
  validateLowStockThreshold(body.lowStockThreshold);
  if (body.imagUrl !== undefined)
    validateProductImageReference(body.imagUrl, sellerId);
  if (Object.keys(body).length === 0)
    throw new OrderError(400, "At least one product field is required");
  if (body.productPrice !== undefined && priceToCents(body.productPrice) === null) {
    throw new OrderError(400, "Product price must have at most two decimal places");
  }
  return db2.transaction(async (tx) => {
    await requireVerifiedSeller(tx, sellerId);
    const [current] = await tx.select().from(sellers_product).where(and(eq(sellers_product.id, productId), eq(sellers_product.userId, sellerId))).for("update").limit(1);
    if (!current)
      throw new OrderError(404, "Product not found");
    const name = body.productName?.trim();
    const initializingLegacy = current.isActive && !current.originalQty && Number(current.productQty) > 0;
    if (name !== undefined) {
      if (!name)
        throw new OrderError(400, "Product name is required");
      if (name.toLowerCase() !== current.productName.trim().toLowerCase()) {
        await tx.execute(sql3`select pg_advisory_xact_lock(hashtext(${sellerId}), hashtext(${`${name.toLowerCase()}:${current.scalingType}`}))`);
        const [duplicate] = await tx.select({ id: sellers_product.id }).from(sellers_product).where(and(eq(sellers_product.userId, sellerId), eq(sellers_product.scalingType, current.scalingType), ne(sellers_product.id, productId), sql3`lower(btrim(${sellers_product.productName})) = ${name.toLowerCase()}`)).limit(1);
        if (duplicate)
          throw new OrderError(409, "Product already listed with this selling unit");
      }
    }
    const now = new Date;
    const [updated] = await tx.update(sellers_product).set({
      ...name !== undefined ? { productName: name } : {},
      ...body.imagUrl !== undefined ? { imagUrl: body.imagUrl } : {},
      ...body.productPrice !== undefined ? { productPrice: body.productPrice.toString() } : {},
      ...body.productType !== undefined ? { productType: body.productType } : {},
      ...body.lowStockThreshold !== undefined ? { lowStockThreshold: body.lowStockThreshold?.toString() ?? null } : {},
      ...body.isMarketable !== undefined ? { isMarketable: body.isMarketable } : {},
      ...initializingLegacy ? { originalQty: current.productQty, publishedAt: now } : {},
      updatedAt: now
    }).where(eq(sellers_product.id, productId)).returning();
    if (initializingLegacy && updated.originalQty) {
      await tx.insert(listing_cycles).values({
        productId,
        vegetableKey: normalizeVegetableName(updated.productName),
        startedAt: now,
        originalQty: updated.originalQty
      });
    }
    return updated;
  });
}

// src/modules/seller/services/seller.product.stock-change.ts
var maxHundredths = 9999999999n;
function fromDecimal(value) {
  const match = /^(\d+)(?:\.(\d{1,2}))?$/.exec(value);
  if (!match)
    throw new OrderError(409, "Product stock is unavailable");
  return BigInt(match[1]) * 100n + BigInt((match[2] ?? "").padEnd(2, "0"));
}
function toDecimal(value) {
  const absolute = value < 0n ? -value : value;
  return `${value < 0n ? "-" : ""}${absolute / 100n}.${(absolute % 100n).toString().padStart(2, "0")}`;
}
function changeSellerProductStock(sellerId, productId, delta, reason) {
  const change = quantityToHundredths(Math.abs(delta));
  if (!change || delta === 0) {
    throw new OrderError(400, "Stock change must be nonzero with at most two decimal places");
  }
  const cleanReason = reason.trim();
  if (!cleanReason || cleanReason.length > 500)
    throw new OrderError(400, "Stock change reason is required");
  const signedChange = delta < 0 ? -change : change;
  return db2.transaction(async (tx) => {
    await requireVerifiedSeller(tx, sellerId);
    const [product] = await tx.select().from(sellers_product).where(and(eq(sellers_product.id, productId), eq(sellers_product.userId, sellerId))).for("update").limit(1);
    if (!product)
      throw new OrderError(404, "Product not found");
    const before = fromDecimal(product.productQty ?? "0.00");
    const after = before + signedChange;
    if (after < 0n || after > maxHundredths) {
      throw new OrderError(409, "Stock change exceeds available quantity or product limit");
    }
    const newCycle = product.isActive && before === 0n && signedChange > 0n;
    const initializeLegacy = product.isActive && product.originalQty === null && after > 0n;
    let originalQty = product.originalQty;
    if (newCycle || initializeLegacy)
      originalQty = toDecimal(after);
    else if (product.isActive && signedChange > 0n && originalQty !== null) {
      const originalAfter = fromDecimal(originalQty) + signedChange;
      if (originalAfter > maxHundredths)
        throw new OrderError(409, "Original quantity exceeds product limit");
      originalQty = toDecimal(originalAfter);
    }
    const now = new Date;
    const [updated] = await tx.update(sellers_product).set({
      productQty: toDecimal(after),
      ...originalQty !== product.originalQty ? { originalQty } : {},
      ...newCycle || initializeLegacy ? { publishedAt: now } : {},
      updatedAt: now
    }).where(eq(sellers_product.id, productId)).returning();
    if ((newCycle || initializeLegacy) && originalQty) {
      await tx.insert(listing_cycles).values({
        productId,
        vegetableKey: normalizeVegetableName(product.productName),
        startedAt: now,
        originalQty
      });
    }
    await tx.insert(product_stock_adjustments).values({
      productId,
      sellerId,
      delta: toDecimal(signedChange),
      beforeQty: toDecimal(before),
      afterQty: toDecimal(after),
      reason: cleanReason
    });
    return updated;
  });
}

// src/modules/seller/services/seller.product.restock.ts
function restockSellerProduct(sellerId, productId, quantity) {
  if (quantity <= 0)
    throw new OrderError(400, "Restock quantity must be positive");
  return changeSellerProductStock(sellerId, productId, quantity, "Restock");
}

// src/modules/seller/services/seller.product.archive.ts
function archiveSellerProduct(sellerId, productId) {
  return db2.transaction(async (tx) => {
    await requireVerifiedSeller(tx, sellerId);
    const [current] = await tx.select().from(sellers_product).where(and(eq(sellers_product.id, productId), eq(sellers_product.userId, sellerId))).for("update").limit(1);
    if (!current)
      throw new OrderError(404, "Product not found");
    if (!current.isActive)
      return current;
    const [product] = await tx.update(sellers_product).set({ isActive: false, updatedAt: new Date }).where(eq(sellers_product.id, productId)).returning();
    return product;
  });
}

// src/modules/seller/services/seller.product.deactivate.ts
