// src/modules/seller/services/seller.product.reactivate.ts
function reactivateSellerProduct(sellerId, productId) {
  return db2.transaction(async (tx) => {
    await tx.execute(sql3`select pg_advisory_xact_lock(hashtext(${sellerId}), 3)`);
    await requireVerifiedSeller(tx, sellerId);
    const [product] = await tx.select().from(sellers_product).where(and(eq(sellers_product.id, productId), eq(sellers_product.userId, sellerId))).for("update").limit(1);
    if (!product)
      throw new OrderError(404, "Product not found");
    if (product.isActive)
      return product;
    if (!product.productQty || Number(product.productQty) <= 0 || !product.productPrice || priceToCents(Number(product.productPrice)) === null || !product.isMarketable) {
      throw new OrderError(409, "Product needs stock, a valid price, and marketability before reactivation");
    }
    const now = new Date;
    const [updated] = await tx.update(sellers_product).set({
      isActive: true,
      originalQty: product.productQty,
      publishedAt: now,
      updatedAt: now
    }).where(eq(sellers_product.id, productId)).returning();
    await tx.insert(listing_cycles).values({
      productId,
      vegetableKey: normalizeVegetableName(product.productName),
      startedAt: now,
      originalQty: product.productQty
    });
    return updated;
  });
}

