// src/utils/order-stock/index.ts
async function restoreOrderStock(tx, orderId) {
  const items = await tx.select({ productId: ordered_items.productId, quantity: ordered_items.quantity }).from(ordered_items).where(eq(ordered_items.ordersId, orderId));
  if (!items.length || items.some((item) => item.quantity === null)) {
    throw new Error("Order items are missing a quantity");
  }
  for (const item of items) {
    const [updated] = await tx.update(sellers_product).set({ productQty: sql3`${sellers_product.productQty} + ${item.quantity}` }).where(eq(sellers_product.id, item.productId)).returning({ id: sellers_product.id });
    if (!updated)
      throw new Error("Order product is missing");
  }
}

// src/utils/trust/index.ts
function recordTrustEvent(tx, input) {
  return tx.insert(trust_events).values(input).onConflictDoNothing({ target: trust_events.eventKey }).returning();
}
function queueTrustNotice(tx, input) {
  return tx.insert(trust_notices).values(input).onConflictDoNothing({ target: trust_notices.noticeKey }).returning();
}
async function recordInquiryDeadlines(tx, inquiry, now) {
  const hours = (now.getTime() - inquiry.createdAt.getTime()) / 3600000;
  if (hours >= 12)
    await queueTrustNotice(tx, {
      noticeKey: `inquiry-reminder:${inquiry.id}`,
      recipientId: inquiry.sellerId,
      orderId: inquiry.orderId,
      kind: "inquiry_12h_reminder"
    });
  if (hours >= 24) {
    await queueTrustNotice(tx, {
      noticeKey: `inquiry-warning:${inquiry.id}`,
      recipientId: inquiry.sellerId,
      orderId: inquiry.orderId,
      kind: "inquiry_24h_warning"
    });
    await queueTrustNotice(tx, {
      noticeKey: `inquiry-buyer:${inquiry.id}`,
      recipientId: inquiry.buyerId,
      orderId: inquiry.orderId,
      kind: "inquiry_24h_buyer_notice"
    });
  }
  if (hours >= 48)
    await recordTrustEvent(tx, {
      eventKey: `inquiry-unanswered:${inquiry.id}`,
      orderId: inquiry.orderId,
      subjectId: inquiry.sellerId,
      kind: "inquiry_non_response",
      classification: "verified",
      sourceId: inquiry.id
    });
}
async function listOrderInquiries(userId, orderId, side) {
  const owner = side === "buyer" ? orders.buyersId : orders.sellersId;
  const [order] = await db2.select({ id: orders.id }).from(orders).where(and(eq(orders.id, orderId), eq(owner, userId))).limit(1);
  if (!order)
    throw new OrderError(404, "Order not found");
  return db2.select().from(order_inquiries).where(eq(order_inquiries.orderId, orderId));
}

// src/modules/seller/services/seller.order.cancel.ts
async function cancelSellerOrder(sellerId, orderId, reason) {
  if (reason.trim().length < 5)
    throw new OrderError(400, "Cancellation reason is required");
  await db2.transaction(async (tx) => {
    await requireVerifiedSeller(tx, sellerId);
    const now = new Date;
    const [cancelled] = await tx.update(orders).set({
      status: "cancelled",
      cancelledBy: "seller",
      cancellationReason: reason.trim(),
      updatedAt: now
    }).where(and(eq(orders.id, orderId), eq(orders.sellersId, sellerId), eq(orders.status, "pending"), gt(orders.expiresAt, now))).returning({ id: orders.id, buyerId: orders.buyersId });
    if (!cancelled) {
      const [current] = await tx.select({ sellerId: orders.sellersId, status: orders.status, expiresAt: orders.expiresAt }).from(orders).where(eq(orders.id, orderId)).limit(1);
      if (!current)
        throw new OrderError(404, "Order not found");
      if (current.sellerId !== sellerId)
        throw new OrderError(403, "This order belongs to another seller");
      if (current.status === "pending" && current.expiresAt && current.expiresAt <= now)
        throw new OrderError(410, "Order has expired");
      throw new OrderError(409, "Order is no longer pending");
    }
    await restoreOrderStock(tx, cancelled.id);
    await recordTrustEvent(tx, {
      eventKey: `seller-cancel:${orderId}`,
      orderId,
      subjectId: sellerId,
      kind: "seller_cancellation",
      classification: "verified"
    });
    await queueTrustNotice(tx, {
      noticeKey: `seller-cancel-warning:${orderId}`,
      recipientId: sellerId,
      orderId,
      kind: "seller_cancellation_warning"
    });
    await queueTrustNotice(tx, {
      noticeKey: `seller-cancel-buyer:${orderId}`,
      recipientId: cancelled.buyerId,
      orderId,
      kind: "seller_cancellation_buyer"
    });
  });
  return getOrder(orderId, sellerId, "seller");
}

