// src/utils/trust/report.ts
function createOrderReport(reporterId, orderId, side, reason, details) {
  if (details.trim().length < 5)
    throw new OrderError(400, "Report details are required");
  return db2.transaction(async (tx) => {
    await requireActiveUser(tx, reporterId, side);
    const owner = side === "buyer" ? orders.buyersId : orders.sellersId;
    const [order] = await tx.select().from(orders).where(and(eq(orders.id, orderId), eq(owner, reporterId))).limit(1);
    if (!order)
      throw new OrderError(404, "Order not found");
    const subjectId = side === "buyer" ? order.sellersId : order.buyersId;
    const [report] = await tx.insert(order_reports).values({
      orderId,
      reporterId,
      subjectId,
      reason,
      details: details.trim()
    }).onConflictDoNothing({ target: [order_reports.orderId, order_reports.reporterId] }).returning();
    if (!report)
      throw new OrderError(409, "You already reported this order");
    await recordTrustEvent(tx, {
      eventKey: `report:${report.id}`,
      orderId,
      subjectId,
      kind: "user_report",
      classification: "allegation",
      sourceId: report.id
    });
    return report;
  });
}

