// src/modules/seller/services/seller.trust.events.ts
async function listSellerTrustEvents(sellerId) {
  const [events, notices] = await Promise.all([
    db2.select({
      id: trust_events.id,
      orderId: trust_events.orderId,
      kind: trust_events.kind,
      policyVersion: trust_events.policyVersion,
      createdAt: trust_events.createdAt
    }).from(trust_events).where(and(eq(trust_events.subjectId, sellerId), eq(trust_events.classification, "verified"), isNull2(trust_events.invalidatedAt))).orderBy(desc(trust_events.createdAt)).limit(100),
    db2.select({
      id: trust_notices.id,
      orderId: trust_notices.orderId,
      kind: trust_notices.kind,
      createdAt: trust_notices.createdAt,
      sentAt: trust_notices.sentAt
    }).from(trust_notices).where(eq(trust_notices.recipientId, sellerId)).orderBy(desc(trust_notices.createdAt)).limit(100)
  ]);
  return { events, notices };
}

// src/modules/seller/services/seller.trust.correct.ts
function correctSellerTrustEvent(sellerId, eventId, reason) {
  return db2.transaction(async (tx) => {
    await requireVerifiedSeller(tx, sellerId);
    const [event] = await tx.select().from(trust_events).where(and(eq(trust_events.id, eventId), eq(trust_events.subjectId, sellerId), eq(trust_events.classification, "verified"))).for("update").limit(1);
    if (!event)
      throw new OrderError(404, "Trust event not found");
    let valid = true;
    if (event.kind === "seller_cancellation") {
      const [order] = await tx.select({ status: orders.status, cancelledBy: orders.cancelledBy }).from(orders).where(eq(orders.id, event.orderId)).limit(1);
      valid = order?.status === "cancelled" && order.cancelledBy === "seller";
    } else if (event.kind === "inquiry_non_response" && event.sourceId) {
      const [inquiry] = await tx.select().from(order_inquiries).where(eq(order_inquiries.id, event.sourceId)).limit(1);
      valid = !!inquiry && inquiry.orderId === event.orderId && (!inquiry.repliedAt || inquiry.repliedAt.getTime() - inquiry.createdAt.getTime() >= 48 * 3600000);
    } else {
      throw new OrderError(400, "This event cannot be corrected automatically");
    }
    const [correction] = await tx.insert(trust_corrections).values({
      eventId,
      requesterId: sellerId,
      reason: reason.trim(),
      outcome: valid ? "confirmed" : "invalidated"
    }).onConflictDoNothing({ target: trust_corrections.eventId }).returning();
    if (!correction)
      throw new OrderError(409, "A correction was already requested");
    if (!valid) {
      await tx.update(trust_events).set({ invalidatedAt: new Date }).where(eq(trust_events.id, eventId));
      await queueTrustNotice(tx, {
        noticeKey: `trust-corrected:${eventId}`,
        recipientId: sellerId,
        orderId: event.orderId,
        kind: "trust_event_corrected"
      });
    }
    return correction;
  });
}

