// src/utils/s3-avatar/index.ts
async function getAvatarDisplayUrl(imageUrl) {
  if (!imageUrl)
    return null;
  let url;
  try {
    url = new URL(imageUrl);
  } catch {
    return null;
  }
  const bucket = process.env.AWS_S3_BUCKET_NAME?.trim();
  const region = process.env.AWS_REGION || "ap-southeast-1";
  const bucketOrigin = `https://${bucket}.s3.${region}.amazonaws.com`;
  if (!bucket || url.origin !== bucketOrigin) {
    return url.protocol === "https:" || url.protocol === "http:" ? imageUrl : null;
  }
  if (url.username || url.password || !url.pathname.startsWith("/avatars/"))
    return null;
  let objectKey;
  try {
    objectKey = decodeURIComponent(url.pathname.slice(1));
  } catch {
    return null;
  }
  return getSignedUrl(getS3Client(), new GetObjectCommand({ Bucket: bucket, Key: objectKey }), { expiresIn: 3600 });
}

// src/modules/seller/services/seller.setup.ts
async function getSellerSetup(userId) {
  return db2.transaction(async (tx) => {
    const [account] = await tx.select({
      id: user.id,
      name: user.name,
      email: user.email,
      image: user.image,
      emailVerified: user.emailVerified,
      twoFactorEnabled: user.twoFactorEnabled,
      isActive: user.isActive,
      role: user.role
    }).from(user).where(eq(user.id, userId)).limit(1);
    if (!account?.isActive)
      throw new OrderError(403, "Account is inactive");
    const [profile] = await tx.select().from(sellers_profile).where(and(eq(sellers_profile.userId, userId), eq(sellers_profile.isCurrent, true))).limit(1);
    const profileComplete = isSellerProfileComplete(profile);
    const sellerVerified = account.emailVerified && profileComplete && !!account.role?.includes("seller");
    return {
      account: { id: account.id, name: account.name, email: account.email, image: await getAvatarDisplayUrl(account.image) },
      profile: profile ?? null,
      emailVerified: account.emailVerified,
      profileComplete,
      sellerVerified,
      twoFactorEnabled: account.twoFactorEnabled,
      badge: sellerVerified ? {
        label: "Verified account",
        explanation: "Email verified and seller profile completed."
      } : null,
      nextStep: !account.emailVerified ? "verify-email" : sellerVerified ? "ready" : "profile"
    };
  });
}

