// src/modules/buyer/services/buyer.order.persist.ts
async function createSellerOrder(tx, checkoutId, buyerId, sellerId, items, expiresAt) {
  if (!items.length || items.some((item) => item.sellerId !== sellerId)) {
    throw new Error("Seller order requires items from exactly one seller");
  }
  const [order] = await tx.insert(orders).values({
    checkoutId,
    buyersId: buyerId,
    sellersId: sellerId,
    totalAmount: sumAmounts(items.map((item) => item.subtotal)),
    expiresAt
  }).returning({ id: orders.id });
  await tx.insert(ordered_items).values(items.map((item) => ({
    ordersId: order.id,
    productId: item.productId,
    productName: item.productName,
    scalingType: item.scalingType,
    quantity: item.quantity.toString(),
    unitPrice: item.unitPrice,
    subtotal: item.subtotal
  })));
  return order.id;
}

// src/modules/buyer/services/buyer.order.reserve.ts
async function unavailableProductError(tx, productId, buyerId) {
  const [product] = await tx.select({ userId: sellers_product.userId }).from(sellers_product).where(eq(sellers_product.id, productId)).limit(1);
  if (!product)
    return new OrderError(404, "Product not found");
  if (product.userId === buyerId) {
    return new OrderError(403, "You cannot order your own product");
  }
  return new OrderError(409, "Product price or quantity is unavailable");
}
async function reserveOrderItem(tx, buyerId, productId, quantity) {
  if (quantityToHundredths(quantity) === null) {
    throw new OrderError(400, "Quantity must be between 0.01 and 99999999 with at most two decimal places");
  }
  const [product] = await tx.update(sellers_product).set({ productQty: sql3`${sellers_product.productQty} - ${quantity}` }).where(and(eq(sellers_product.id, productId), ne(sellers_product.userId, buyerId), isNotNull(sellers_product.productPrice), gt(sellers_product.productPrice, "0"), gte(sellers_product.productQty, quantity.toString()), eq(sellers_product.isActive, true), eq(sellers_product.isMarketable, true))).returning();
  if (!product)
    throw await unavailableProductError(tx, productId, buyerId);
  await requireActiveUser(tx, product.userId, "seller");
  await requireVerifiedSeller(tx, product.userId);
  return {
    productId: product.id,
    sellerId: product.userId,
    productName: product.productName,
    scalingType: product.scalingType,
    quantity,
    unitPrice: product.productPrice,
    subtotal: multiplyPrice(product.productPrice, quantity)
  };
}

// src/modules/buyer/services/buyer.order.create.ts
function requestFingerprint(productId, quantity) {
  return createHash5("sha256").update(`${productId.toLowerCase()}:${quantity}`).digest("hex");
}
async function createDirectOrder(buyerId, body, rawKey) {
  const { productId, quantity } = body;
  ensureOrderQrSecret();
  const idempotencyKey = rawKey.trim();
  if (!idempotencyKey || idempotencyKey.length > 128) {
    throw new OrderError(400, "Invalid Idempotency-Key header");
  }
  const fingerprint = requestFingerprint(productId, quantity);
  const result = await db2.transaction(async (tx) => {
    await tx.execute(sql3`
      select pg_advisory_xact_lock(
        hashtext(${buyerId}),
        hashtext(${idempotencyKey})
      )
    `);
    const [existing] = await tx.select({
      id: checkouts.id,
      requestFingerprint: checkouts.requestFingerprint
    }).from(checkouts).where(and(eq(checkouts.buyersId, buyerId), eq(checkouts.idempotencyKey, idempotencyKey))).limit(1);
    if (existing) {
      if (existing.requestFingerprint !== fingerprint) {
        throw new OrderError(409, "Idempotency key was used for another order");
      }
      const [previousOrder] = await tx.select({ id: orders.id }).from(orders).where(eq(orders.checkoutId, existing.id)).limit(1);
      if (!previousOrder)
        throw new Error("Checkout is missing its order");
      return { orderId: previousOrder.id, replayed: true };
    }
    await requireActiveUser(tx, buyerId, "buyer");
    const item = await reserveOrderItem(tx, buyerId, productId, quantity);
    const [checkout] = await tx.insert(checkouts).values({
      buyersId: buyerId,
      idempotencyKey,
      requestFingerprint: fingerprint
    }).returning({ id: checkouts.id });
    const orderId = await createSellerOrder(tx, checkout.id, buyerId, item.sellerId, [item], new Date(Date.now() + 24 * 60 * 60 * 1000));
    return { orderId, replayed: false };
  });
  return {
    order: await getBuyerOrder(result.orderId, buyerId),
    replayed: result.replayed
  };
}

