// src/modules/buyer/model/buyer.order.inquiry.ts
var buyerInquiryParams = t.Object({ id: t.String({ format: "uuid" }) });
var buyerInquiryBody = t.Object({ question: t.String({ minLength: 1, maxLength: 1000 }) });

// src/modules/buyer/services/buyer.order.inquiry.create.ts
function createBuyerInquiry(buyerId, orderId, question) {
  if (!question.trim())
    throw new OrderError(400, "Question is required");
  return db2.transaction(async (tx) => {
    await requireActiveUser(tx, buyerId, "buyer");
    await tx.execute(sql3`select pg_advisory_xact_lock(hashtext(${orderId}), 2)`);
    const [order] = await tx.select().from(orders).where(and(eq(orders.id, orderId), eq(orders.buyersId, buyerId))).limit(1);
    if (!order)
      throw new OrderError(404, "Order not found");
    if (order.status !== "pending" || !order.expiresAt || order.expiresAt <= new Date) {
      throw new OrderError(409, "Only active orders accept new inquiries");
    }
    const [open] = await tx.select({ id: order_inquiries.id }).from(order_inquiries).where(and(eq(order_inquiries.orderId, orderId), isNull2(order_inquiries.repliedAt))).limit(1);
    if (open)
      throw new OrderError(409, "An inquiry is already awaiting a reply");
    const [inquiry] = await tx.insert(order_inquiries).values({
      orderId,
      buyerId,
      sellerId: order.sellersId,
      question: question.trim()
    }).returning();
    return inquiry;
  });
}

